# Then verify that the enumeration of valid N values yields at least 3 distinct values.

def prime_power_list(n):
    # returns list of prime powers p^e for n
    res = []
    d = 2
    while d * d <= n:
        cnt = 0
        while n % d == 0:
            n //= d
            cnt += 1
        if cnt > 0:
            res.append(d ** cnt)
        d += 1
    if n > 1:
        res.append(n)
    return res

def enumerate_Ns(k):
    n2 = 2 * k
    pp = prime_power_list(n2)
    r = len(pp)
    triples = set()
    # assign each prime power to one of three groups, requiring all groups nonempty
    # and enforcing distinct group products
    for code in range(3 ** r):
        prods = [1, 1, 1]
        counts = [0, 0, 0]
        t = code
        for i in range(r):
            g = t % 3
            t //= 3
            counts[g] += 1
            prods[g] *= pp[i]
        if 0 in counts:
            continue  # empty group => one of a,b,c would be 1, not allowed
